    int m, n;
    scanf("%d %d", &m, &n);
    if (m > n) {
        int temp = m;
        m = n;
        n = temp;
    }
    bool first = true;
    for (int i = m; i <= n; i++) {
        if (is_prime(i)) {
            if (!first) {
                printf("");
            }
            printf("%d ", i);
            first = false;
