{
    int n,i,j,k;
    scanf("%d",&n);
    k=n/2;
    for(j=1;j<=k+1;j++)
    {
        for(i=1;i<=j+k;i++)
        {
            if(i<=k+j&&i>k-j+1)
                printf("* ");
            else printf("  ");
        }
        printf("\n");
    }
    for(j=k+2;j<=n;j++)
    {
        for(i=n;i>j-k-1;i--)
        {
            if(i<=n-j+k+1&&i>j-k-1)
                printf("* ");
            else printf("  ");
        }
        printf("\n");
    }
}
```

