#include <stdio.h>
int fx(int target) {
    if (target == 1) {
        return 1;
    }
    int a = 1, b = 1, c;
    int index = 2;
    while (1) {
        c = a + b;
        index++;
        if (c >= target) {
            return index;
        }
        a = b;
        b = c;
    }
}
int main() {
